	<section aria-label="Interactive material typography">
		<div class="materials"><div><button class:selected={finish==='velvet'} aria-pressed={finish==='velvet'} onclick={()=>finish='velvet'}>Velvet nap</button><button class:selected={finish==='enamel'} aria-pressed={finish==='enamel'} onclick={()=>finish='enamel'}>Polished glaze</button></div><span>{finish==='velvet'?'A MEMORY OF DIRECTION':'FROSTED TO POLISHED, WITH A STROKE'}</span></div>
